const binaryData = $input.item.binary;

if (!binaryData || Object.keys(binaryData).length === 0) {
  throw new Error('No file received. Make sure you are sending the PDF as form-data in Postman with key type set to File.');
}

// Get whatever field name Postman used (data, file, etc.)
const fieldName = Object.keys(binaryData)[0];
const field = binaryData[fieldName];

if (!field.data) {
  throw new Error('Binary field found but has no data. Re-check your Postman setup.');
}

return [{
  json: {
    base64: field.data,
    mimeType: field.mimeType || 'application/pdf',
    fileName: field.fileName || 'paper.pdf'
  }
}];

