const response = $input.item.json;

// Extract Gemini's HTML summary
const summary = response.candidates?.[0]?.content?.parts?.[0]?.text;

if (!summary) {
  throw new Error('Gemini returned no content. Check your API key or PDF format.');
}

// Get paper filename from extract node
const paperName = $('📦 Extract Base64').item.json.fileName || 'AI Research Paper';

// Build styled HTML email
const now = new Date();
const date = now.toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});
const time = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

const emailHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: 'Segoe UI', Arial, sans-serif; background: #f0f2f5; }
    .wrapper { max-width: 680px; margin: 30px auto; }
    .header { background: linear-gradient(135deg, #0f0c29, #302b63, #24243e); padding: 40px; border-radius: 12px 12px 0 0; }
    .header h1 { color: #fff; font-size: 26px; font-weight: 700; letter-spacing: -0.5px; }
    .header p { color: #a0aec0; font-size: 14px; margin-top: 6px; }
    .badge { display: inline-flex; align-items: center; gap: 8px; background: rgba(255,255,255,0.1); color: #e2e8f0; padding: 8px 16px; border-radius: 30px; font-size: 13px; font-weight: 600; margin-top: 16px; border: 1px solid rgba(255,255,255,0.15); }
    .body { background: #fff; padding: 40px; }
    .body h2 { font-size: 17px; font-weight: 700; margin: 28px 0 12px; padding: 10px 16px; border-radius: 8px; }
    .body h2:nth-of-type(1) { background: #ebf8ff; border-left: 4px solid #3182ce; color: #2b6cb0; }
    .body h2:nth-of-type(2) { background: #fff5f5; border-left: 4px solid #e53e3e; color: #c53030; }
    .body h2:nth-of-type(3) { background: #f0fff4; border-left: 4px solid #38a169; color: #276749; }
    .body ul { padding: 0 0 0 20px; }
    .body li { color: #4a5568; font-size: 15px; line-height: 1.9; margin-bottom: 4px; }
    .footer { background: #f7fafc; padding: 22px 40px; border-radius: 0 0 12px 12px; border-top: 1px solid #e2e8f0; display: flex; justify-content: space-between; align-items: center; }
    .footer p { color: #a0aec0; font-size: 12px; }
    .footer strong { color: #718096; }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="header">
      <h1>🧠 AI Paper Digest</h1>
      <p>${date} at ${time}</p>
      <div class="badge">📄 ${paperName}</div>
    </div>
    <div class="body">
      ${summary}
    </div>
    <div class="footer">
      <p>Generated by your <strong>n8n AI Paper Digest</strong> 🤖</p>
      <p><strong>Powered by Gemini</strong></p>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    html: emailHtml,
    subject: `🧠 AI Digest: ${paperName}`,
    paperName: paperName,
    timestamp: now.toISOString()
  }
}];
